// Bundles the new-order alert sound and wires it up for push notifications.
// The native folders are regenerated by `expo prebuild` / EAS, so everything
// has to be added here, not by hand.
//
// - alert_sound.mp3: played in the foreground by react-native-sound
//   (src/services/notificationService.ts).
// - Android: a dedicated "new_orders" notification channel that uses
//   res/raw/alert_sound. Only pushes sent with that channel_id play it; every
//   other notification stays on the default channel / system sound.
// - iOS: alert_sound.caf (iOS notification sounds can't be MP3), played only
//   when the APNs payload sets `sound: "alert_sound.caf"`.
const fs = require('fs');
const path = require('path');
const {
  withDangerousMod,
  withXcodeProject,
  withMainApplication,
  IOSConfig,
} = require('@expo/config-plugins');

const MP3_SOURCE = 'assets/sound/notification2.mp3';
const MP3_NAME = 'alert_sound.mp3';
const CAF_SOURCE = 'assets/sound/alert_sound.caf';
const CAF_NAME = 'alert_sound.caf';

// Keep in sync with NOTIFICATION_CONFIG.newOrderChannelId and the backend.
const CHANNEL_ID = 'new_orders';
const CHANNEL_NAME = 'New orders';

const withAndroidSound = config =>
  withDangerousMod(config, [
    'android',
    async cfg => {
      const rawDir = path.join(cfg.modRequest.platformProjectRoot, 'app/src/main/res/raw');
      fs.mkdirSync(rawDir, { recursive: true });
      fs.copyFileSync(path.join(cfg.modRequest.projectRoot, MP3_SOURCE), path.join(rawDir, MP3_NAME));
      return cfg;
    },
  ]);

const CHANNEL_MARKER = '// [withAlertSound] new order channel';

const CHANNEL_FN = `
  ${CHANNEL_MARKER}
  private fun createNewOrderChannel() {
    if (android.os.Build.VERSION.SDK_INT < android.os.Build.VERSION_CODES.O) return
    val manager = getSystemService(android.app.NotificationManager::class.java) ?: return
    if (manager.getNotificationChannel("${CHANNEL_ID}") != null) return
    val sound = android.net.Uri.parse("android.resource://" + packageName + "/raw/alert_sound")
    val attrs = android.media.AudioAttributes.Builder()
      .setUsage(android.media.AudioAttributes.USAGE_NOTIFICATION)
      .setContentType(android.media.AudioAttributes.CONTENT_TYPE_SONIFICATION)
      .build()
    val channel = android.app.NotificationChannel(
      "${CHANNEL_ID}", "${CHANNEL_NAME}", android.app.NotificationManager.IMPORTANCE_HIGH
    ).apply {
      setSound(sound, attrs)
      enableVibration(true)
    }
    manager.createNotificationChannel(channel)
  }
`;

const withNewOrderChannel = config =>
  withMainApplication(config, cfg => {
    let src = cfg.modResults.contents;
    if (src.includes(CHANNEL_MARKER)) return cfg;

    src = src.replace(/super\.onCreate\(\)\n/, match => `${match}    createNewOrderChannel()\n`);
    src = src.replace(/\n}\s*$/, `\n${CHANNEL_FN}}\n`);
    cfg.modResults.contents = src;
    return cfg;
  });

const withIosSound = config =>
  withXcodeProject(config, cfg => {
    const projectName = cfg.modRequest.projectName;

    for (const [source, name] of [
      [MP3_SOURCE, MP3_NAME],
      [CAF_SOURCE, CAF_NAME],
    ]) {
      const dest = path.join(cfg.modRequest.platformProjectRoot, projectName, name);
      fs.copyFileSync(path.join(cfg.modRequest.projectRoot, source), dest);

      const filepath = path.join(projectName, name);
      if (!cfg.modResults.hasFile(filepath)) {
        cfg.modResults = IOSConfig.XcodeUtils.addResourceFileToGroup({
          filepath,
          groupName: projectName,
          isBuildFile: true,
          project: cfg.modResults,
        });
      }
    }
    return cfg;
  });

module.exports = config => withIosSound(withNewOrderChannel(withAndroidSound(config)));
